                        if i + 1 < len(line) and line[i + 1] == '"':
                            cur.append('"')
                            i += 2  # Skip the next quote
                        else:
                            in_quote = False
                            i += 1
                    else:
                        in_quote = True
                        i += 1
                elif ch == ',' and not in_quote:
                    fields.append("".join(cur))
                    cur = []
                    i += 1
                else:
                    cur.append(ch)
                    i += 1
            fields.append("".join(cur))
            rows.append(fields)
        return rows

