import heapq

class MinHeap:
    def __init__(self):
        self.elements = []
        self._counter = 0

    def push(self, item):
        # item is expected to be a tuple (cost, path)
        cost, path = item
        heapq.heappush(self.elements, (cost, self._counter, path))
        self._counter += 1

    def pop(self):
        cost, _, path = heapq.heappop(self.elements)
        return (cost, path)

    def __len__(self):
        return len(self.elements)

